update public.lessons l set enhancements = $ench${"industryStory":"A team's end-to-end suite took nearly forty minutes and flaked most runs. Tracing the failures showed the vast majority landed on the login screen — a step none of those tests were meant to exercise. Moving to a single setup-project login with reused storage state cut the run to under fifteen minutes and removed a whole category of flake overnight. Login was still covered — by two tests that existed to cover it, and nothing else.","visualAid":{"type":"flow","title":"Log in once, reuse everywhere","steps":[{"label":"Setup project runs first","detail":"auth.setup.ts drives the login form a single time"},{"label":"Save the session","detail":"context.storageState() writes cookies and tokens to a JSON file"},{"label":"Tests depend on setup","detail":"dependencies: [setup] guarantees it finished before they start"},{"label":"Every test starts authenticated","detail":"use.storageState loads the session into a fresh context"}]},"davidTip":"Always assert a genuine signed-in signal before calling `storageState`. Saving too early — right after the click, before the dashboard renders — captures a session that is not really logged in, and you get a baffling suite where every test fails at the first authenticated action.","miniChallenge":"Add a second dedicated UI test that logs in through the form and asserts the dashboard appears. Keep it as the only test that touches the login screen, and confirm the rest of your suite still reuses storage state."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 8 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"badGood":{"label":"testing permissions","bad":"~~~ts\n// One shared session, so this only ever proves the happy path for whoever is logged in.\ntest('admin panel works', async ({ page }) => {\n  await page.goto('/admin');\n  await expect(page.getByRole('heading', { name: 'Admin' })).toBeVisible();\n});\n~~~","good":"~~~ts\n// user.spec.ts runs under the 'user' project with the standard-user state.\ntest('a standard user is refused the admin panel', async ({ page }) => {\n  const response = await page.goto('/admin');\n  expect(response?.status()).toBe(403);\n  await expect(page.getByText('You do not have access')).toBeVisible();\n});\n~~~"},"davidTip":"When a permissions test goes red, check which role's state file it loaded before you touch the application. A common false alarm is a test in the wrong project — running admin-only assertions against the standard-user session — which looks like a product bug but is really a config mistake.","miniChallenge":"Add a third identity: an unauthenticated visitor, using `storageState: { cookies: [], origins: [] }` so the project starts logged out. Write a test proving a protected page redirects that visitor to login."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 8 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"industryStory":"A team moved all their authentication setup from the login form to a single API call and cut minutes off every run. A sprint later a redesign quietly broke the login page's submit button — and nobody noticed for days, because no automated test drove the form any more. The lesson was not \"don't use API login\"; it was \"keep one UI login test as the canary\". They added it back and it caught the next such regression the same afternoon.","visualAid":{"type":"comparison","title":"UI login vs programmatic login for setup","headers":["Aspect","UI login","Programmatic (API) login"],"rows":[["Speed","Slow — renders and drives a whole page","Fast — one HTTP request"],["Points of failure","Many (render, validation, redirect)","Few (one endpoint)"],["Best used for","Covering the login journey itself","Setup for every other test"],["Depends on the login UI","Yes","No"]]},"davidTip":"Always assert the login response succeeded before saving state. A failed API login that goes unchecked writes an empty, logged-out storage file, and then every test downstream fails at its first authenticated step — a confusing red suite whose real cause is one missing `expect(response.ok())`.","miniChallenge":"Instrument both approaches: time your UI login setup, then time the programmatic one, and record the difference. Multiply it by the number of roles you authenticate to see the real saving across a full run."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 8 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"badGood":{"label":"test data uniqueness","bad":"~~~ts\ntest('user can register', async ({ page }) => {\n  // Hardcoded email — passes once, then fails with \"email already in use\".\n  await page.getByLabel('Email').fill('test.user@example.com');\n  // ...\n});\n~~~","good":"~~~ts\nimport { makeUser } from './factories/user';\n\ntest('user can register', async ({ page }) => {\n  const user = makeUser(); // unique email every run\n  await page.getByLabel('Email').fill(user.email);\n  // ...\n});\n~~~"},"visualAid":{"type":"comparison","title":"Choosing a data source","headers":["Source","Good for","Watch out for"],"rows":[["Fixture (static)","Small, read-only values","Breaks if a test mutates or deletes it"],["Factory (generated)","Data a test creates and owns","Keep defaults realistic and readable"],["Seeded data","Shared reference data many tests read","No test should own or mutate it"]]},"davidTip":"Make a factory generate valid data by default and force the test to opt into invalid data explicitly. A test called \"rejects a malformed email\" reads far better as `makeUser({ email: 'not-an-email' })` than as a wall of hardcoded fields where the one that matters is buried.","miniChallenge":"Refactor an existing test that hardcodes a unique value to use a factory instead. Run the whole suite twice in a row and confirm the test now passes both times."}$ench$::jsonb
